import{_ as i}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as o,a as t,b as r,c as s,d as l,e as n,f as d}from"./chunks/M-SS-NFcert.CC0MK3SI.js";import{_ as c}from"./chunks/M-SS.C4V7iNpZ.js";import{_ as p,o as u,c as m,a3 as g}from"./chunks/framework.g9mfNVRQ.js";const z=JSON.parse('{"title":"Stato del sistema","description":"","frontmatter":{"source_hash":"972ebaa79c","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/troubleshoot/systemstatus.md","filePath":"it/troubleshoot/systemstatus.md"}'),h={name:"it/troubleshoot/systemstatus.md"};function v(b,e,f,_,x,w){return u(),m("div",null,[...e[0]||(e[0]=[g('<div class="admonition xdrip"><p class="admonition-title"><img src="'+i+'" style="zoom:75%;"></p><p> Stato del sistema</p></div><p>Stato del sistema fornisce informazioni interne sullo stato del collector di xDrip (da un sensore o come follower), oltre che sulla condivisione, sui follower e sugli smartwatch collegati direttamente.</p><p>Puoi condividere uno screenshot con il pulsante di condivisione di Android in alto a destra.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;">Stato del sistema<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><h3 id="classic-status-page" tabindex="-1">Pagina di stato classica <a class="header-anchor" href="#classic-status-page" aria-label="Permalink to &quot;Pagina di stato classica {#classic-status-page}&quot;">​</a></h3><p>Questa pagina mostra informazioni sulla versione attualmente installata.</p><div class="admonition xdripitem"><p class="admonition-title"><div style="background-color:DodgerBlue;color:white;text-align:center;">  Classic Status Page </div></p><p> Versione: a2bbca9-2024.11.26</p></div><p>Le informazioni sulla versione ti permettono di <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">trovare rapidamente la release o pre-release corrispondente</a>. Prima della data della versione vedrai la versione di build.</p><p>Qualsiasi nome di versione che mostra informazioni aggiuntive, come debug, dev, il nome di uno smartwatch, carelink, è una <a href="./../install/download.html#forked-versions">versione fork</a> di xDrip e potrebbe non contenere tutte le funzioni più recenti dell&#39;app rilasciata (ma probabilmente qualcuna in più).</p><p>In questa pagina trovi il tipo di sorgente dati (quella che hai selezionato per ricevere i valori di glicemia).</p><div class="admonition xdripitem"><p class="admonition-title">Sorgente Dati:</p></div><p>La riga successiva mostra la dimensione del database di xDrip: la quantità di memoria che usa sul telefono.</p><div class="admonition xdripitem"><p class="admonition-title">Dimensione Database:</p></div><p>Nel caso di un sensore fisico, dopo il tipo di sorgente dati vedrai il nome del dispositivo Bluetooth effettivamente collegato a xDrip. Puoi anche vedere lo stato della connessione; tieni presente che alcuni sensori si collegano solo per poco tempo ogni 5 minuti, quindi Non connesso potrebbe non essere un vero problema.</p><div class="admonition xdripitem"><p class="admonition-title">Dispositivo Bluetooth:</p></div><div class="admonition xdripitem"><p class="admonition-title">Stato della connessione:</p></div><div class="admonition xdripitem"><p class="admonition-title">Sensore attivato:</p></div><p>Poiché questa pagina non si aggiorna automaticamente, devi toccare le frecce circolari per aggiornarla.</p><img src="'+t+'" style="zoom:75%;"><h4 id="restart-collector-forget-device" tabindex="-1">Riavvia Collector - Dimentica questo dispositivo <a class="header-anchor" href="#restart-collector-forget-device" aria-label="Permalink to &quot;Riavvia Collector - Dimentica questo dispositivo {#restart-collector-forget-device}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> RIAVVIA COLLECTOR </span> <span style="background-color:white;color:black;"> DIMENTICA QUESTO DISPOSITIVO </span></p></div><p>Riavvia Collector riavvia il meccanismo interno di raccolta dati di xDrip. L&#39;effetto dipende dalla sorgente dati.</p><p>Dimentica questo dispositivo ha effetto solo quando xDrip è collegato a un dispositivo tramite Bluetooth.<br> Il dispositivo verrà scollegato e dovrai fare una scansione Bluetooth dal menu principale per ripristinare la connessione.</p><h3 id="advanced-status-page" tabindex="-1">Pagina di stato avanzata <a class="header-anchor" href="#advanced-status-page" aria-label="Permalink to &quot;Pagina di stato avanzata {#advanced-status-page}&quot;">​</a></h3><p>La maggior parte delle sorgenti dati ha una scheda di stato avanzata. Scorri il dito sullo schermo verso sinistra per visualizzarla.</p><img src="'+c+'" style="zoom:75%;"><h5 id="buggy-samsung" tabindex="-1">Buggy Samsung <a class="header-anchor" href="#buggy-samsung" aria-label="Permalink to &quot;Buggy Samsung {#buggy-samsung}&quot;">​</a></h5><p>Rinominato Buggy Handset perché anche altri dispositivi presentano questa non conformità.</p><h5 id="buggy-handset" tabindex="-1">Buggy Handset <a class="header-anchor" href="#buggy-handset" aria-label="Permalink to &quot;Buggy Handset {#buggy-handset}&quot;">​</a></h5><p>Non è un errore, indica solo che xDrip sta <a href="https://github.com/NightscoutFoundation/xDrip/issues/435" target="_blank" rel="noreferrer">correggendo</a> una non conformità ad Android di alcuni dispositivi.<br> Si consiglia di <a href="./../use/misc.html#wake-workarounds">attivarlo</a> in caso di perdita di dati.</p><img src="'+r+'" style="zoom:75%;"><h5 id="slowest-wake-up" tabindex="-1">Slowest wake-up <a class="header-anchor" href="#slowest-wake-up" aria-label="Permalink to &quot;Slowest wake-up {#slowest-wake-up}&quot;">​</a></h5><p>Indica quando xDrip ha ricevuto i dati rispetto all&#39;orario previsto. Qualche secondo è accettabile, ma alcuni minuti possono essere il segnale di un problema di connettività.</p><img src="'+s+'" style="zoom:75%;"><h4 id="g6-g7-1-and-1" tabindex="-1">G6, G7, 1 e 1+ <a class="header-anchor" href="#g6-g7-1-and-1" aria-label="Permalink to &quot;G6, G7, 1 e 1+ {#g6-g7-1-and-1}&quot;">​</a></h4><p>Consulta le pagine dedicate a <a href="./g6.html">G6/ONE</a> e <a href="./g7.html">G7/ONE+</a>. Maggiori dettagli sulla connettività <a href="https://navid200.github.io/xDrip/docs/Connectivity-troubleshoot.html" target="_blank" rel="noreferrer">qui</a>.</p><h4 id="libre-bluetooth" tabindex="-1">Libre Bluetooth <a class="header-anchor" href="#libre-bluetooth" aria-label="Permalink to &quot;Libre Bluetooth {#libre-bluetooth}&quot;">​</a></h4><p>Se usi un bridge, vedi la pagina dedicata <a href="./librebridge.html">qui</a>.</p><p>Se usi un Libre 2 direttamente (cioè senza bridge), vedi la pagina dedicata <a href="./libre2direct.html">qui</a>.</p><h4 id="xdrip-sync-follower" tabindex="-1">xDrip Sync Follower <a class="header-anchor" href="#xdrip-sync-follower" aria-label="Permalink to &quot;xDrip Sync Follower {#xdrip-sync-follower}&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Lavori in corso</p><p>A luglio 2024 Google ha chiuso la <a href="https://firebase.google.com/docs/cloud-messaging/migrate-v1" target="_blank" rel="noreferrer">API Firebase</a> deprecata che xDrip usava per xDrip Sync.<br> Aggiorna xDrip a una versione del <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.07.23" target="_blank" rel="noreferrer">23 luglio 2024</a> o successiva.</p></div><p>Il follower xDrip è davvero semplice da <a href="./../use/syncsetup.html">configurare</a>. Se hai problemi, nella maggior parte dei casi si tratta della connessione di rete o dei servizi Google Play.<br> Avere anche <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> come soluzione follower di riserva è consigliato quando risolvi problemi o segui un bambino.</p><img src="'+l+'" style="zoom:75%;"><p>I follower si aggiungono all&#39;elenco man mano che vengono identificati; se rimuovi un follower, potrebbe volerci un po&#39; di tempo prima che venga effettivamente tolto dall&#39;elenco.</p><p>Per i problemi di configurazione iniziale vedi <a href="./../install/xdripfollower.html">qui</a>.</p><h4 id="nightscout-follower" tabindex="-1">Nightscout Follower <a class="header-anchor" href="#nightscout-follower" aria-label="Permalink to &quot;Nightscout Follower {#nightscout-follower}&quot;">​</a></h4><p>La pagina di stato avanzata mostra l&#39;attività durante lo scaricamento da Nightscout. Se non ci sono dati disponibili, assicurati di avere valori di glicemia attuali in Nightscout.</p><p>In caso di errore di scaricamento, se il tuo sito Nightscout viene aggiornato regolarmente dal dispositivo master e vedi errori di download NS, potrebbe trattarsi di problemi di rete. Disattiva il Wi-Fi o i dati della SIM e poi prova il contrario, per escludere questo problema.</p><p>Se non ha mai funzionato, assicurati di aver <a href="./../install/nightscoutfollower.html">configurato</a> correttamente l&#39;URL del follower.</p><img src="'+n+'" style="zoom:75%;"><p>Le versioni di Android più vecchie possono usare certificati scaduti e quindi impedire il funzionamento del follower Nightscout. Non c&#39;è soluzione.</p><img src="'+d+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',54)])])}const P=p(h,[["render",v]]);export{z as __pageData,P as default};
